import { readFile } from 'node:fs/promises';
import { expect, test } from '@playwright/test';
import { fixture, schoolUrl, signIn } from './support';

/**
 * F18 flows, end to end (launch checklist 5.2): a CSV export generated by
 * the API's export worker and downloaded through the single-use download
 * capability; global search (Ctrl+K) to a record; a print view rendered for
 * paper.
 */

test('a School Admin exports the student directory as CSV', async ({ page }) => {
  test.setTimeout(120_000);
  await signIn(page, fixture().users.schoolAdmin);
  await page.goto(schoolUrl('/school/reports'));

  const card = page
    .locator('div')
    .filter({ has: page.getByRole('heading', { name: 'Student Directory' }) })
    .filter({ has: page.getByRole('button', { name: 'Request Export' }) })
    .last();
  await card.getByRole('button', { name: 'Request Export' }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByRole('button', { name: 'Generate CSV' }).click();

  const downloadButton = dialog.getByRole('button', { name: 'Download CSV' });
  await expect(downloadButton).toBeVisible({ timeout: 60_000 });
  const [download] = await Promise.all([page.waitForEvent('download'), downloadButton.click()]);
  expect(download.suggestedFilename()).toMatch(/\.csv$/);
  const csv = await readFile(await download.path(), 'utf8');
  const lines = csv.trim().split(/\r?\n/);
  // A header and one row per provisioned student ("Student L<n>").
  expect(lines[0]).toContain('First Name');
  expect(lines.length).toBeGreaterThan(fixture().students.length);
  expect(csv).toContain(',Student,L0,');
});

test('global search finds an exam by title and opens it', async ({ page }) => {
  const { examId, examTitle } = fixture();
  await signIn(page, fixture().users.schoolAdmin);
  await page.goto(schoolUrl('/school'));
  await expect(page.getByRole('button', { name: 'Search records (Ctrl+K)' })).toBeVisible();

  await page.keyboard.press('Control+k');
  const input = page.getByLabel('Global search input');
  await expect(input).toBeFocused();
  await input.fill(examTitle);
  await expect(page.getByRole('option', { name: new RegExp(examTitle) })).toBeVisible();
  await page.keyboard.press('Enter');
  await page.waitForURL((url) => url.pathname.includes(examId));
});

test('the results print view renders for paper', async ({ page }) => {
  const { examId, examTitle } = fixture();
  await signIn(page, fixture().users.teacher);
  await page.emulateMedia({ media: 'print' });
  await page.goto(schoolUrl(`/print/exams/${examId}/results`));
  await expect(page.getByText(examTitle).filter({ visible: true }).first()).toBeVisible();
  // Screen-only chrome (navigation, the print button) stays off the page.
  await expect(page.getByRole('navigation')).toHaveCount(0);
});
